CREATE TABLE IF NOT EXISTS economic_network_intelligence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), profile_id uuid NOT NULL, relationship_count integer NOT NULL DEFAULT 0, verified_relationship_count integer NOT NULL DEFAULT 0, trusted_evidence_count integer NOT NULL DEFAULT 0, network_score numeric(5,2) NOT NULL DEFAULT 0, risk_level text NOT NULL DEFAULT 'unknown', drivers jsonb NOT NULL DEFAULT '[]'::jsonb, calculated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_network_intelligence_profile ON economic_network_intelligence(profile_id,calculated_at DESC);